/** A block as pageQuery returns it: the section's content plus Sanity's _type and _key. */
export type SectionBlock =
  | (HeroContent & { _type: 'heroSection'; _key: string })
  | (PageHeaderContent & { _type: 'pageHeaderSection'; _key: string })
  | (SplitContent & { _type: 'splitSection'; _key: string })
  | (MediaContent & { _type: 'mediaSection'; _key: string })
  | (ContentContent & { _type: 'contentSection'; _key: string })
  | (PostsContent & { _type: 'postsSection'; _key: string })
  | (TeamContent & { _type: 'teamSection'; _key: string })
  | (NewsletterContent & { _type: 'newsletterSection'; _key: string })
  | (CtaContent & { _type: 'ctaSection'; _key: string });

/** Renders a page's sections with the React components (server component; Header is the only client one). */
export function PageBuilder({ sections }: { sections?: SectionBlock[] | null }) {
  return (
    <>
      {(sections ?? []).map((block) => {
        switch (block._type) {
          case 'heroSection':
            return <Hero key={block._key} {...block} />;
          case 'pageHeaderSection':
            return <PageHeader key={block._key} {...block} />;
          case 'splitSection':
            return <Split key={block._key} {...block} />;
          case 'mediaSection':
            return <Media key={block._key} {...block} />;
          case 'contentSection':
            return <Content key={block._key} {...block} />;
          case 'postsSection':
            return <Posts key={block._key} {...block} />;
          case 'teamSection':
            return <Team key={block._key} {...block} />;
          case 'newsletterSection':
            return <Newsletter key={block._key} {...block} />;
          case 'ctaSection':
            return <Cta key={block._key} {...block} />;
          default:
            return null;
        }
      })}
    </>
  );
}
